import pyomo.environ as pyo

DATA = {
    "water_use": {"liquid": 40, "foam": 60},
    "alcohol_use": {"liquid": 50, "foam": 40},
    "water_avail": 2000,
    "alcohol_avail": 2100,
    "max_liquid": 30,
    "hands_per_unit": {"liquid": 30, "foam": 20},
    "exceed_margin": 1,  # foam must exceed liquid by at least 1 unit
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.PRODUCTS = pyo.Set(initialize=["liquid", "foam"])

    model.liquid = pyo.Var(
        domain=pyo.NonNegativeIntegers, bounds=(0, d["max_liquid"])
    )
    model.foam = pyo.Var(domain=pyo.NonNegativeIntegers, bounds=(0, None))

    def obj_rule(m):
        return (
            d["hands_per_unit"]["liquid"] * m.liquid
            + d["hands_per_unit"]["foam"] * m.foam
        )

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    def water_rule(m):
        return (
            d["water_use"]["liquid"] * m.liquid
            + d["water_use"]["foam"] * m.foam
            <= d["water_avail"]
        )

    model.water_limit = pyo.Constraint(rule=water_rule)

    def alcohol_rule(m):
        return (
            d["alcohol_use"]["liquid"] * m.liquid
            + d["alcohol_use"]["foam"] * m.foam
            <= d["alcohol_avail"]
        )

    model.alcohol_limit = pyo.Constraint(rule=alcohol_rule)

    def exceed_rule(m):
        return m.foam >= m.liquid + d["exceed_margin"]

    model.foam_exceeds_liquid = pyo.Constraint(rule=exceed_rule)

    def liquid_cap_rule(m):
        return m.liquid <= d["max_liquid"]

    model.liquid_cap = pyo.Constraint(rule=liquid_cap_rule)

    return model


